package com.studyspace.controller;
import java.time.Instant; import java.time.LocalDate; import java.util.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.studyspace.model.Task; import com.studyspace.repo.TaskRepository;
@RestController @RequestMapping("/api/tasks") public class TaskController { private final TaskRepository tasks; public TaskController(TaskRepository t){tasks=t;}
 @GetMapping public ResponseEntity<?> list(HttpServletRequest r){String uid=user(r);if(uid==null)return unauthorized();return ResponseEntity.ok(tasks.findByUserOrderByCompletedAscDueDateAscCreatedAtDesc(uid));}
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object>b,HttpServletRequest r){String uid=user(r);if(uid==null)return unauthorized();String title=str(b,"title"),subject=str(b,"subject"),date=str(b,"dueDate");if(title.isBlank()||subject.isBlank()||date.isBlank())return ResponseEntity.badRequest().body(Map.of("message","Title, subject, and due date are required"));try{Task t=new Task();t.setUser(uid);t.setTitle(title);t.setSubject(subject);t.setDueDate(LocalDate.parse(date.substring(0,10)));t.setPriority(priority(str(b,"priority")));t.setNotes(str(b,"notes"));tasks.save(t);return ResponseEntity.status(201).body(t);}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Invalid task details"));}}
 @PutMapping("/{id}") public ResponseEntity<?> update(@PathVariable String id,@RequestBody Map<String,Object>b,HttpServletRequest r){String uid=user(r);if(uid==null)return unauthorized();Task t=tasks.findByIdAndUser(id,uid).orElse(null);if(t==null)return ResponseEntity.status(404).body(Map.of("message","Task not found"));try{if(b.containsKey("title"))t.setTitle(str(b,"title"));if(b.containsKey("subject"))t.setSubject(str(b,"subject"));if(b.containsKey("dueDate"))t.setDueDate(LocalDate.parse(str(b,"dueDate").substring(0,10)));if(b.containsKey("priority"))t.setPriority(priority(str(b,"priority")));if(b.containsKey("completed"))t.setCompleted(Boolean.parseBoolean(String.valueOf(b.get("completed"))));if(b.containsKey("notes"))t.setNotes(str(b,"notes"));t.setUpdatedAt(Instant.now());return ResponseEntity.ok(tasks.save(t));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Invalid task details"));}}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable String id,HttpServletRequest r){String uid=user(r);if(uid==null)return unauthorized();Task t=tasks.findByIdAndUser(id,uid).orElse(null);if(t==null)return ResponseEntity.status(404).body(Map.of("message","Task not found"));tasks.delete(t);return ResponseEntity.ok(Map.of("message","Task deleted"));}
 private String user(HttpServletRequest r){return (String)r.getAttribute("userId");} private ResponseEntity<?> unauthorized(){return ResponseEntity.status(401).body(Map.of("message","Please sign in again"));} private String str(Map<String,Object>b,String k){Object v=b.get(k);return v==null?"":String.valueOf(v).trim();} private String priority(String p){return Set.of("Low","Medium","High").contains(p)?p:"Medium";} }
